import { useUpload } from '@dreadnought/react/logic';
import { UploadAdapter } from '@dreadnought/react/unstyled';
export function Example() {
  const upload = useUpload({ multiple: true });
  return <UploadAdapter upload={upload} label="Прикрепить файлы" dropzone />;
}

import { useUpload } from '@dreadnought/react/logic';
export function Example() {
  const upload = useUpload({ accept: '.pdf', multiple: true, maxCount: 3 });
  return <button type="button" onClick={() => { void upload.pick(); }}>Выбрать документы</button>;
}
